const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();

async function main() {
  const userId = 'cmmrunf9l0000cpijlrn58jpw';

  // Create a WeeklyPlan
  const plan = await prisma.weeklyPlan.create({
    data: {
      userId: userId,
      weekStart: new Date()
    }
  });

  console.log('WeeklyPlan created:', plan.id);
  return plan.id;
}

main()
  .catch(e => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
EOF
